payload:
$ErrorActionPreference = 'Stop'
$repo = 'C:\Users\Xxkan\HeavenBridgeRepo'
Set-Location $repo
$origin = (git remote get-url origin).Trim()
if ($origin -notmatch 'fengie/mhw-mods') { throw "Unexpected origin: $origin" }
git fetch --all --prune | Out-Null
$baseline = (git rev-parse origin/main).Trim()
$current = (git branch --show-current).Trim()
$default = (git symbolic-ref --short refs/remotes/origin/HEAD 2>$null | Out-String).Trim()
$worktreeText = (& git worktree list --porcelain | Out-String).Trim()
$worktreeBranches = @()
foreach($line in ($worktreeText -split "[\r\n]+")) {
  if($line -like 'branch refs/heads/*') { $worktreeBranches += ($line -replace '^branch refs/heads/','') }
}
$openPrBranches = @()
if (Get-Command gh -ErrorAction SilentlyContinue) {
  try {
    $json = gh pr list --repo fengie/mhw-mods --state open --limit 200 --json headRefName 2>$null
    if($LASTEXITCODE -eq 0 -and $json) {
      $openPrBranches = @((ConvertFrom-Json $json) | ForEach-Object { $_.headRefName })
    }
  } catch {}
}
$rows = @()
$refs = & git for-each-ref --format='%(refname:short)|%(objectname)|%(committerdate:iso8601)|%(authorname)' refs/heads/ refs/remotes/origin/
foreach($line in $refs) {
  if(-not $line){continue}
  $p=$line -split '\|',4
  $full=$p[0]; $sha=$p[1]; $date=$p[2]; $author=$p[3]
  if($full -eq 'origin/HEAD'){continue}
  $scope = if($full.StartsWith('origin/')){'remote'}else{'local'}
  $name = if($scope -eq 'remote'){$full.Substring(7)}else{$full}
  if($name -eq 'main'){
    $rows += [ordered]@{scope=$scope;name=$name;sha=$sha;date=$date;author=$author;baseline=$true}
    continue
  }
  $isAncestor=$false
  & git merge-base --is-ancestor $full origin/main 2>$null
  if($LASTEXITCODE -eq 0){$isAncestor=$true}
  $treeEqual=$false
  & git diff --quiet origin/main $full 2>$null
  if($LASTEXITCODE -eq 0){$treeEqual=$true}
  $plus=0;$minus=0
  if(-not $isAncestor -and -not $treeEqual){
    $cherry=@(& git cherry origin/main $full 2>$null)
    $plus=@($cherry | Where-Object {$_ -like '+ *'}).Count
    $minus=@($cherry | Where-Object {$_ -like '- *'}).Count
  }
  $ab=(& git rev-list --left-right --count "origin/main...$full" 2>$null | Out-String).Trim()
  $inWorktree = $worktreeBranches -contains $name
  $openPr = $openPrBranches -contains $name
  $special = ($name -eq 'heaven-bridge' -or $name -eq 'main' -or $name -like 'release/*')
  $safeProof = if($isAncestor){'ancestor-of-main'}elseif($treeEqual){'tree-equal-main'}elseif($plus -eq 0 -and $minus -gt 0){'patch-equivalent-to-main'}else{''}
  $rows += [ordered]@{
    scope=$scope;name=$name;sha=$sha;date=$date;author=$author;aheadBehind=$ab;
    ancestorOfMain=$isAncestor;treeEqualMain=$treeEqual;cherryPlus=$plus;cherryMinus=$minus;
    safeProof=$safeProof;inWorktree=$inWorktree;openPR=$openPr;special=$special
  }
}
[ordered]@{
  repo=$repo;origin=$origin;baseline=$baseline;current=$current;defaultRemote=$default;
  worktreeBranches=$worktreeBranches;openPrBranches=$openPrBranches;rows=$rows
} | ConvertTo-Json -Depth 7
